using System.Linq;
using UnityEngine;
using UnityEngine.UI;
namespace CafeLife {
 public sealed partial class CafeUI {
  RectTransform focusedHud;Text focusedStats,focusedRecipe,focusedFeedback,focusedMeter;Text[] focusedOrders=new Text[2];Button[] focusedOrderButtons=new Button[2];Button focusedPrimary,focusedFoam,focusedArt;Image focusedFill;string focusSection="business";
  Button FocusButton(RectTransform parent,string text,Vector2 position,Vector2 size,UnityEngine.Events.UnityAction action){int n=parent.childCount;Button(parent,text,new Vector2(0,1),position,size,action);var node=parent.GetChild(n);var label=node.GetComponentInChildren<Text>();label.fontSize=23;var metric=label.GetComponent<CafeFontSize>();if(metric)metric.size=23;return node.GetComponent<Button>();}
  void BuildFocusedHud(){focusedHud=Rect("Kafe odaklı dokunmatik kontroller",safe,Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero);
   var top=Panel(focusedHud,new Vector2(0,1),new Vector2(1,1),new Vector2(0,-92),Vector2.zero,panel);focusedStats=Text(top,"",23,TextAnchor.MiddleLeft);focusedStats.rectTransform.offsetMin=new Vector2(24,8);focusedStats.rectTransform.offsetMax=new Vector2(-210,-8);
   FocusButton(focusedHud,"KAFE",new Vector2(1080,-86),new Vector2(180,76),()=>game.OpenOperations());
   for(int i=0;i<2;i++){int index=i;var b=FocusButton(focusedHud,"",new Vector2(20,-260-i*158),new Vector2(300,142),()=>{var orders=game.GetComponent<CafeFocusedMode>().Orders;if(index<orders.Length)game.GetComponent<CafeFocusedMode>().SelectOrder(orders[index]);});focusedOrderButtons[i]=b;focusedOrders[i]=b.GetComponentInChildren<Text>();focusedOrders[i].alignment=TextAnchor.MiddleLeft;focusedOrders[i].fontSize=20;focusedOrders[i].GetComponent<CafeFontSize>().size=20;}
   var card=Panel(focusedHud,new Vector2(0,1),new Vector2(0,1),new Vector2(345,-188),new Vector2(930,-105),panel);focusedRecipe=Text(card,"",22,TextAnchor.MiddleCenter);
   focusedFoam=FocusButton(focusedHud,"SÜTÜ KÖPÜRT",new Vector2(955,-205),new Vector2(305,82),()=>game.expansion.Action("foam"));
   focusedArt=FocusButton(focusedHud,"LATTE ART ÇİZ",new Vector2(955,-300),new Vector2(305,82),()=>game.expansion.Action("art"));
   FocusButton(focusedHud,"STOKLARI DOLDUR",new Vector2(955,-395),new Vector2(305,82),()=>game.Restock());
   FocusButton(focusedHud,"BARDAĞI AT",new Vector2(955,-490),new Vector2(305,82),()=>game.Discard());
   var meter=Panel(focusedHud,new Vector2(0,1),new Vector2(0,1),new Vector2(350,-490),new Vector2(930,-456),new Color(.03f,.07f,.06f,.95f));var fill=Panel(meter,Vector2.zero,Vector2.one,new Vector2(3,3),new Vector2(-3,-3),new Color(.65f,.83f,.55f));focusedFill=fill.GetComponent<Image>();focusedFill.type=Image.Type.Filled;focusedFill.fillMethod=Image.FillMethod.Horizontal;
   focusedMeter=Text(meter,"",19,TextAnchor.MiddleCenter);
   focusedPrimary=FocusButton(focusedHud,"SİPARİŞİ BAŞLAT",new Vector2(350,-625),new Vector2(580,112),()=>game.GetComponent<CafeFocusedMode>().ClickPrimary());var press=focusedPrimary.gameObject.AddComponent<CafeCounterPress>();press.mode=game.GetComponent<CafeFocusedMode>();
   focusedFeedback=Label(focusedHud,Vector2.zero,Vector2.one,new Vector2(24,12),new Vector2(-24,-640),21,TextAnchor.MiddleCenter);
   foreach(Transform child in safe)if(child!=menu&&child!=focusedHud)child.gameObject.SetActive(false);
  }
  void UpdateFocusedHud(){if(!focusedHud)return;var mode=game.GetComponent<CafeFocusedMode>();var pour=game.GetComponent<CafeLattePour>();focusedHud.gameObject.SetActive(!game.Paused&&!(pour&&pour.Active));
   focusedStats.text=CafeNames.CafeUpper+" · "+game.data.money+" coin · Gün "+game.data.day+"\nServis "+game.data.served+" · Seri "+game.data.hundred.combo+" · Çekirdek "+game.data.beans+" / Süt "+game.data.milk;
   var orders=mode.Orders;for(int i=0;i<2;i++){focusedOrderButtons[i].interactable=i<orders.Length&&orders[i].state==CafeCustomer.State.Waiting;if(i>=orders.Length){focusedOrders[i].text="Yeni müşteri bekleniyor...";continue;}var c=orders[i];focusedOrders[i].text=(mode.selectedOrder==c?"✓ ":"")+CafeExpansion.Names[c.identity]+" · "+(c.state==CafeCustomer.State.Entering?"Geliyor":"Sabır %"+Mathf.CeilToInt(c.patience))+"\n"+Economy.Recipes[c.recipe].name+"\n"+CafeService.PreferenceLabel(c);}
   var cup=game.cup;focusedPrimary.GetComponentInChildren<Text>().text=mode.ActionLabel;focusedPrimary.interactable=cup!=null||orders.Any(c=>c.state==CafeCustomer.State.Waiting);
   focusedRecipe.text=cup!=null?Economy.Recipes[cup.recipe].name+"\n"+string.Join(" → ",CafeGame.IdealSteps(Economy.Recipes[cup.recipe]).Select(s=>(cup.steps.Contains(s)?"✓ ":"")+StepName(s))):"Siparişe dokun, sonra bardağı al.\nKahveyi burada hazırlayıp servis et.";
   focusedFoam.interactable=cup!=null&&cup.hasMilk&&!cup.coldCup&&!cup.foamed&&!cup.lidded&&game.expansion.foamTime<=0;
   focusedArt.interactable=cup!=null&&cup.foamed&&cup.brewed&&!cup.art&&!cup.lidded;
   if(game.brewTime>0&&cup!=null){focusedFill.fillAmount=Mathf.Clamp01(cup.yield/(cup.dose*2.8f));focusedFill.color=Mathf.Abs(cup.yield/cup.dose-2)<.2f?new Color(.3f,.8f,.45f):new Color(.8f,.55f,.3f);focusedMeter.text=cup.yield.ToString("0")+" g / hedef "+(cup.dose*2).ToString("0")+" g · Şimdi kesebilirsin";}
   else if(mode.heldAction!=""){focusedFill.fillAmount=mode.holdProgress;focusedMeter.text="Hazırlanıyor · %"+Mathf.RoundToInt(mode.holdProgress*100);}
   else if(game.expansion.foamTime>0){focusedFill.fillAmount=1-game.expansion.foamTime/2.5f;focusedMeter.text="Süt köpürtülüyor · "+(cup!=null?cup.milkTemperature.ToString("0"):"20")+"°C";}
   else{focusedFill.fillAmount=0;focusedMeter.text=cup!=null&&cup.brewed?CafeHundred.Taste(cup):"Basılı tutulan işlemlerde çubuğu doldur.";}
   focusedFeedback.text=game.noticePinned||Time.unscaledTime<game.noticeUntil?string.Join("\n",game.notice.Split('\n').Take(2)):"";
  }
  void FocusMenuButton(string text,int row,bool right,UnityEngine.Events.UnityAction action){FocusButton(menu,text,new Vector2(right?660:30,-260-row*86),new Vector2(590,76),()=>{action();if(game.Paused)ShowMenu("operations");});}
  void BuildFocusedMenu(){string[] ids={"business","supply","upgrade","report","settings"};string[] names={"KAFE","TEDARİK","YÜKSELT","RAPOR","AYAR"};for(int i=0;i<5;i++){string section=ids[i];FocusButton(menu,names[i],new Vector2(30+i*245,-155),new Vector2(235,60),()=>{focusSection=section;ShowMenu("operations");});}var mode=game.GetComponent<CafeFocusedMode>();var x=game.expansion;
   if(focusSection=="business") {FocusMenuButton("Kafe "+(x.Data.open?"AÇIK · kapat":"KAPALI · aç"),0,false,()=>{x.Data.open=!x.Data.open;game.Save();});FocusMenuButton("Kafeyi temizle",1,false,()=>x.Action("clean_cafe"));FocusMenuButton("Makine temizliği · 5 coin",2,false,()=>x.Action("clean_machine"));FocusMenuButton("Barista mesaisi · "+(x.Data.staffOn?"Açık":"Kapalı"),3,false,()=>{x.Data.staffOn=!x.Data.staffOn;game.Save();});FocusMenuButton("Günlük servis hedefi · "+x.Data.dayServed+" / 8",0,true,()=>x.DailyReward());FocusMenuButton("Ustalık hedefi · +120 coin",1,true,()=>game.GetComponent<CafeHundred>().Claim());FocusMenuButton("Tema değiştir · 15 coin",2,true,()=>x.SetDecor("theme"));FocusMenuButton("Stokları tezgâha doldur",3,true,()=>game.Restock());}
   else if(focusSection=="supply"){FocusMenuButton("35 çekirdek · 25 coin",0,false,()=>mode.Supply("beans"));FocusMenuButton("25 süt + 15 buz · 20 coin",1,false,()=>mode.Supply("milk"));FocusMenuButton("Bardak ve kapak paketi · 18 coin",2,false,()=>mode.Supply("packaging"));FocusMenuButton("Karma tedarik paketi · 35 coin",3,false,()=>{if(game.Buy("stock"))game.Restock();});FocusMenuButton("Parasız kaldım · acil destek",4,false,()=>game.RescueStock());BodyText("KAPIYA TESLİMAT\n\nSatın aldığın paket tezgâha aktarılır.\n\nÇekirdek "+game.data.beans+" · Süt "+game.data.milk+"\nBuz "+game.data.ice+"\nSıcak bardak "+game.data.cupsHot+" · Soğuk "+game.data.cupsCold+"\n\nYürümene gerek yok.",true);}
   else if(focusSection=="upgrade"){FocusMenuButton("Espresso makinesi Lv."+game.data.machine+" · "+game.data.machine*90+" coin",0,false,()=>game.Buy("machine"));FocusMenuButton("Dekor Lv."+game.data.decor+" · "+(50+game.data.decor*30)+" coin",1,false,()=>game.Buy("decor"));FocusMenuButton("Yeni masa · "+(140+game.data.tables*30)+" coin",2,false,()=>game.Buy("table"));FocusMenuButton("Barista işe al · 350 coin",0,true,()=>game.Buy("staff"));FocusMenuButton("Barista eğitimi · Lv."+game.data.baristaLevel,1,true,()=>game.UpgradeMainBarista());FocusMenuButton("Duvar paleti değiştir · 15 coin",2,true,()=>x.SetDecor("wall"));}
   else if(focusSection=="report"){BodyText(game.GetComponent<CafeHundred>().Summary(),false);string text="TARİFLERİN AÇILIŞI\n\nBaşlangıç: Espresso ve Latte\n5 servis: Americano\n10 servis: Karamel ve Vanilya\n20 servis: Buzlu Latte ve Americano\n35 servis: tüm tarifler\n\nBugün net: "+(x.Data.dayIncome-x.Data.dayExpenses)+" coin\n\n"+string.Join("\n",x.Data.reviews.Take(3));BodyText(text,true);}
   else{FocusMenuButton("Müzik · %"+Mathf.RoundToInt(x.Data.music*100),0,false,()=>{x.Data.music=x.Data.music>=.99f?0:x.Data.music+.25f;game.ApplyAudio();game.Save();});FocusMenuButton("Efekt sesi · %"+Mathf.RoundToInt(x.Data.effects*100),1,false,()=>{x.Data.effects=x.Data.effects>=.99f?0:x.Data.effects+.25f;game.ApplyAudio();game.Save();});FocusMenuButton("Büyük yazı · "+(game.data.hundred.largeText?"Açık":"Kapalı"),2,false,()=>{game.data.hundred.largeText=!game.data.hundred.largeText;game.Save();});FocusMenuButton("Kontrast · "+(game.data.hundred.contrast?"Yüksek":"Normal"),3,false,()=>{game.data.hundred.contrast=!game.data.hundred.contrast;game.Save();});BodyText("TEZGÂH KONTROLLERİ\n\nSiparişe dokun.\nAna düğme sıradaki işlemi gösterir.\nÖğütme ve dökmede basılı tut.\nEspressoyu hedef gramda kes.\nSütlü kahveye köpük ve desen ekle.\nKapağı takıp servis et.\n\nFareyle de aynı kontrolleri deneyebilirsin.",true);}
   var info=Label(menu,Vector2.zero,new Vector2(.5f,0),new Vector2(30,12),new Vector2(-20,95),20,TextAnchor.MiddleLeft);info.text=game.data.money+" coin\n"+string.Join("\n",game.notice.Split('\n').Take(2));
   FocusButton(menu,"OYUNA DÖN",new Vector2(660,-705),new Vector2(590,76),()=>game.Continue());
  }
  void BuildFocusedHome(string pageName){FocusButton(menu,"KAFEYE DEVAM ET",new Vector2(60,-265),new Vector2(570,104),()=>game.Continue());FocusButton(menu,"KAFEYİ YÖNET",new Vector2(60,-385),new Vector2(570,104),()=>game.OpenOperations());FocusButton(menu,"YENİ OYUN",new Vector2(60,-505),new Vector2(570,104),()=>ShowMenu("confirm"));BodyText("KAFENDE SERBESTÇE GEZ\n\nWASD / ok tuşları: yürü\nFare: etrafa bak\nE: baktığın müşteri veya makineyle etkileş\nShift: hızlı yürü\nTab: kafe yönetimi\nEsc: duraklat\n\nMobil: sol çubukla yürü, sağ alanda bak.",true);}
  void BuildFocusedConfirm(){BodyText("Yeni oyun başlamadan mevcut kayıt yedeklenir.\n\nMevcut ilerlemeyle devam etmek için vazgeç.",true);FocusButton(menu,"YENİ OYUNU BAŞLAT",new Vector2(60,-330),new Vector2(570,104),()=>game.RequestNewGame());FocusButton(menu,"VAZGEÇ",new Vector2(60,-465),new Vector2(570,104),()=>ShowMenu("home"));}
